const body = $json.body || $json;
let skus = body.skus || [];

if (typeof skus === 'string') {
  skus = skus.split(/[\n,;]+/).map(s => s.trim()).filter(Boolean);
}
if (!Array.isArray(skus)) {
  skus = [skus];
}

skus = skus.map(s => String(s).trim()).filter(Boolean);

if (skus.length === 0) {
  return [{ json: { skus: [], skusJson: '[]' } }];
}

return [{
  json: {
    skus: skus,
    skusJson: JSON.stringify(skus)
  }
}];

const inputSkus = $('Preparar SKUs').first().json.skus || [];
const rows = $input.all().map(item => item.json);

const sku_map = {};
for (const s of inputSkus) {
  sku_map[s] = { cat: [], trad: [] };
}

for (const row of rows) {
  if (!row || !row.sku) continue;
  const sku = String(row.sku || '').trim();
  const mlb = String(row.mlb || '').trim().toUpperCase();
  const isCat = Number(row.is_catalog || 0);
  const status = String(row.status_in_marketplace || 'active');

  if (sku && mlb && mlb.startsWith('MLB')) {
    if (!sku_map[sku]) {
      sku_map[sku] = { cat: [], trad: [] };
    }
    if (isCat === 1) {
      sku_map[sku].cat.push([mlb, status]);
    }
    else {
      sku_map[sku].trad.push([mlb, status]);
    }
  }
}

return [{
  json: {
    success: true,
    sku_map: sku_map,
    count: Object.keys(sku_map).length
  }
}];
